	private static readonly string DIALOG_TITLE = "Go To ...";

	private static readonly string EXPRESSION_ANCHOR_NAME = "GoTo_Expression";
	private static readonly string FILE_OFFSET_ANCHOR_NAME = "GoTo_File_Offset";
	private static readonly int DEFAULT_MAX_GOTO_ENTRIES = 10;

